  for k in ["config","research","identities","universe"]{need(digest(&opening["priorBank"][k])==digest(&bank[k]),"OPENING_SCOPE")?;}need(time(&opening["state"]["lastAvailableAt"]) ?<=time(&bank["cutoff"])?,"OPENING_CLOCK")?;
  let mut state=opening["state"].clone();state["bankHash"]=json!(digest(&bank));state["lastAvailableAt"]=bank["cutoff"].clone();state["barriers"]=json!({"global":bank["cutoff"],"markets":{}});
  for w in state["wallets"].as_object_mut().ok_or("OPENING_WALLETS")?.values_mut(){invalidate(&mut w["state"],None,&bank["cutoff"],if bank["schemaVersion"]==4{"native_transport_continuation_boundary"}else{"owned_risk_continuation_boundary"});for st in w["state"]["strategies"].as_object_mut().unwrap().values_mut(){let count=st["pending"].as_object().unwrap().len() as i64;st["expiredIntents"]=json!(num(&st["expiredIntents"])?+count);st["pending"]=object();}}
